<script setup>
defineProps({windows:{type:Array,default:()=>[]},modelValue:{default:''},busy:Boolean});
const emit=defineEmits(['update:modelValue','refresh','read','all']);
const key=w=>String(w.id??w.pid);
</script>
<template><div class="read-toolbar workspace-actions" aria-label="读取操作"><button :disabled="busy" @click="emit('refresh')">刷新</button><select aria-label="游戏窗口" :value="modelValue" :disabled="busy" @change="emit('update:modelValue',$event.target.value)"><option v-if="!windows.length" value="">未检测到游戏窗口</option><option v-for="w in windows" :key="key(w)" :value="key(w)">{{w.title||'游戏窗口'}}</option></select><button :disabled="busy||!modelValue" @click="emit('read',modelValue)">读取所选</button><slot name="current"/><button class="primary" :disabled="busy" @click="emit('all')">{{busy?'正在读取…':'读取全部'}}</button><slot/></div></template>
<style scoped>.read-toolbar{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap;min-width:0}.read-toolbar button,.read-toolbar select,.read-toolbar :slotted(button){font:inherit;font-size:13px!important;line-height:18px!important;height:36px;min-height:36px;padding:8px 12px;border:1px solid #dfd3bf;border-radius:6px;background:#fffcf6;color:#3b413b;box-sizing:border-box}.read-toolbar select{max-width:230px;min-width:140px}.read-toolbar button{cursor:pointer}.read-toolbar .primary{background:#456052;border-color:#456052;color:white}.read-toolbar button:disabled,.read-toolbar select:disabled{opacity:.5;cursor:default}@media(max-width:650px){.read-toolbar{justify-content:flex-start}.read-toolbar select{max-width:100%}}</style>
